// Afrikaans Studies lesson drafts (lib/course-translation-drafts-af.ts, generated by
// scripts/build-af-course-drafts.mjs from docs/study-translation-reviews/afrikaans-2026-10-31/).
// Every lesson must reach the learner as a labelled draft while its English still matches, and fall
// back to English the moment the English changes, so a quiz can never drift from its answer.
//
// Run with:
//   node --import ./tests/register-alias.mjs --test tests/af-course-drafts.test.ts

import assert from 'node:assert/strict';
import test from 'node:test';

import { COURSE_MODULES } from '@/lib/course-modules';
import { resolveLearnerLessonPresentation } from '@/lib/course-localization';
import { regionalModuleDraftBadge, resolveCourseModulePresentation } from '@/lib/course-module-translation-drafts';
import { AFRIKAANS_COURSE_DRAFTS } from '@/lib/course-translation-drafts-af';

const numbers = (s: string): string[] => [...(s.match(/\d+(?:[.,]\d+)?/g) ?? [])].sort();

test('every module and lesson shows its Afrikaans draft, with the English answer index', () => {
  for (const mod of COURSE_MODULES) {
    const modulePresentation = resolveCourseModulePresentation(mod, 'af');
    assert.equal(modulePresentation.status, 'draft', `${mod.id}: module title is not drafted`);
    assert.notEqual(modulePresentation.title, mod.title, `${mod.id}: module title is still English`);
    assert.equal(regionalModuleDraftBadge(mod, 'af'), 'Afrikaans AI draft · review pending');
    for (const lesson of mod.lessons) {
      const { content, status } = resolveLearnerLessonPresentation(lesson, 'af');
      assert.equal(status, 'draft', `${lesson.id}: not shown as an Afrikaans draft`);
      assert.notEqual(content.title, lesson.title, `${lesson.id}: title is still English`);
      assert.equal(content.body.split('\n\n').length, lesson.body.split('\n\n').length, `${lesson.id}: paragraph count differs`);
      assert.deepEqual(content.quiz.map((q) => q.correct), lesson.quiz.map((q) => q.correct), `${lesson.id}: answer index differs`);
    }
  }
});

test('every figure the English writes in digits survives in the Afrikaans draft', () => {
  const pairs: Array<{ sourceEnglish: string; afrikaansDraft: string }> = [];
  const walk = (v: unknown) => {
    if (Array.isArray(v)) v.forEach(walk);
    else if (v && typeof v === 'object') {
      if ('sourceEnglish' in v && 'afrikaansDraft' in v) pairs.push(v as { sourceEnglish: string; afrikaansDraft: string });
      else Object.values(v).forEach(walk);
    }
  };
  walk(AFRIKAANS_COURSE_DRAFTS);
  assert.equal(pairs.length, 646);
  for (const { sourceEnglish, afrikaansDraft } of pairs) {
    const left = numbers(afrikaansDraft);
    const missing = numbers(sourceEnglish).filter((n) => { const i = left.indexOf(n); if (i < 0) return true; left.splice(i, 1); return false; });
    assert.deepEqual(missing, [], `figure(s) dropped from ${JSON.stringify(sourceEnglish.slice(0, 60))}`);
  }
});

test('a changed English lesson falls back to English instead of showing a stale draft', () => {
  const lesson = COURSE_MODULES[0].lessons[0];
  const edited = { ...lesson, quiz: lesson.quiz.map((q, i) => (i === 0 ? { ...q, q: `${q.q} (revised)` } : q)) };
  const { content, status } = resolveLearnerLessonPresentation(edited, 'af');
  assert.equal(status, 'english-fallback');
  assert.equal(content.title, lesson.title);
  // isiXhosa and the other regional languages are untouched by the Afrikaans path.
  assert.equal(resolveLearnerLessonPresentation(lesson, 'xh').status, 'draft');
  assert.equal(resolveLearnerLessonPresentation(lesson, 'en').status, 'approved');
});
